```js
import { registerLoadingRegion } from '@dot-loaders/core/region';
import { registerSkeletonText } from '@dot-loaders/core/skeleton';

registerLoadingRegion();
registerSkeletonText();
const region = document.querySelector('#summary');

// Called by the application when a new refresh begins.
export function beginRefresh(requestId) {
  region.update({ state: 'refreshing', cycle: requestId });
}

// Called separately when the application's matching request settles.
export function showResult(requestId, text) {
  if (region.cycle !== requestId) return;
  region.querySelector('[data-summary]').textContent = text;
  region.update({ state: 'ready', cycle: requestId });
}
